INSERT INTO ab.permissions(id)SELECT 'hr_'||unnest(ARRAY['view','create','edit','private','documents','document_update','document_review','leave_approve','account_status','task_manage','task_delegate','evaluation_models','evaluation_weights','evaluation_view','evaluation_approve','evaluation_visibility','salary_view','salary_edit','payroll_prepare','payroll_approve','awards','deductions','coaching','termination','clearance','eos_view','reserve','library_view','library_download','library_manage','configure','audit','export'])ON CONFLICT DO NOTHING;
CREATE TABLE ab.hr_employees(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,user_id uuid,employee_number bigint NOT NULL,manager_id uuid,department_id uuid,job_title text NOT NULL DEFAULT '',state text NOT NULL CHECK(state IN('Active','OnLeave','Notice','Ended','Inactive')),hired_on date NOT NULL,payload_cipher text NOT NULL,private_cipher text NOT NULL,search_tokens text[]NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,employee_number),UNIQUE(tenant_id,user_id),UNIQUE(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,user_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,manager_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,department_id)REFERENCES ab.departments(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_assignments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,job_title text NOT NULL,effective_on date NOT NULL,until_on date,CHECK(until_on IS NULL OR until_on>=effective_on),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_document_records(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,version_id uuid NOT NULL,kind text NOT NULL,expires_on date,responsible_id uuid,company_responsible boolean NOT NULL DEFAULT false,state text NOT NULL DEFAULT 'Submitted'CHECK(state IN('Submitted','Approved','Rejected')),reviewed_by uuid,reviewed_at timestamptz,payload_cipher text NOT NULL,UNIQUE(tenant_id,version_id),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,version_id)REFERENCES ab.document_versions(tenant_id,id),FOREIGN KEY(tenant_id,responsible_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,reviewed_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_leave_balances(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,effective_on date NOT NULL,days numeric(10,2)NOT NULL,reference text NOT NULL,reason text NOT NULL,UNIQUE(tenant_id,employee_id,reference),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_leaves(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,kind text NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,days numeric(10,2)NOT NULL CHECK(days>0),state text NOT NULL DEFAULT 'Requested'CHECK(state IN('Requested','Approved','Rejected','Returned')),suspend_account boolean NOT NULL DEFAULT true,suspended_at timestamptz,approved_by uuid,payload_cipher text NOT NULL,revision integer NOT NULL DEFAULT 1,CHECK(ends_on>=starts_on),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_account_holds(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,user_id uuid NOT NULL,source_key text NOT NULL,reason text NOT NULL,resolved_at timestamptz,resolved_by uuid,UNIQUE(tenant_id,source_key),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,user_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,resolved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_delegations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,original_id uuid NOT NULL,substitute_id uuid NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,state text NOT NULL DEFAULT 'Active'CHECK(state IN('Active','Extended','Returned','Transferred')),payload_cipher text NOT NULL,CHECK(original_id<>substitute_id AND ends_on>=starts_on),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,original_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,substitute_id)REFERENCES ab.hr_employees(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.tasks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,employee_id uuid NOT NULL,original_employee_id uuid NOT NULL,task_number bigint NOT NULL,source_type text NOT NULL,source_id uuid,source_key text NOT NULL,state text NOT NULL DEFAULT 'Open'CHECK(state IN('Open','InProgress','Review','Completed','Closed')),due_on date NOT NULL,priority text NOT NULL CHECK(priority IN('normal','high','urgent')),completed_at timestamptz,payload_cipher text NOT NULL,revision integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,company_id,source_key),UNIQUE(tenant_id,task_number),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,original_employee_id)REFERENCES ab.hr_employees(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_task_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,task_id uuid NOT NULL,kind text NOT NULL,payload_cipher text NOT NULL,FOREIGN KEY(tenant_id,task_id)REFERENCES ab.tasks(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_models(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,job_title text NOT NULL,version integer NOT NULL,payload_cipher text NOT NULL,UNIQUE(tenant_id,company_id,job_title,version),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_reviews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,month date NOT NULL CHECK(extract(day from month)=1),score integer CHECK(score BETWEEN 0 AND 10000),payload_cipher text NOT NULL,UNIQUE(tenant_id,employee_id,company_id,month),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_coaching(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('session','improved','escalated')),session_on date NOT NULL,review_on date NOT NULL,payload_cipher text NOT NULL,FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_compensation(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,effective_on date NOT NULL,currency char(3)NOT NULL,payload_cipher text NOT NULL,UNIQUE(tenant_id,employee_id,effective_on),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_decisions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,month date NOT NULL,kind text NOT NULL CHECK(kind IN('bonus','allowance','deduction','correction')),amount numeric(21,3)NOT NULL CHECK(amount>0),reference text NOT NULL,state text NOT NULL DEFAULT 'Requested'CHECK(state IN('Requested','Approved','Rejected')),payload_cipher text NOT NULL,approved_by uuid,UNIQUE(tenant_id,employee_id,company_id,month,kind,reference),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_payroll(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,month date NOT NULL CHECK(extract(day from month)=1),state text NOT NULL DEFAULT 'Draft'CHECK(state IN('Draft','Approved')),currency char(3)NOT NULL,net numeric(21,3)NOT NULL CHECK(net>=0),voucher_id uuid,payload_cipher text NOT NULL,approved_by uuid,UNIQUE(tenant_id,employee_id,month),UNIQUE(tenant_id,voucher_id),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,voucher_id)REFERENCES ab.finance_vouchers(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.hr_payroll_decisions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,payroll_id uuid NOT NULL,decision_id uuid NOT NULL,UNIQUE(tenant_id,decision_id),FOREIGN KEY(tenant_id,payroll_id)REFERENCES ab.hr_payroll(tenant_id,id),FOREIGN KEY(tenant_id,decision_id)REFERENCES ab.hr_decisions(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
