CREATE TABLE ab.hr_terminations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,employee_id uuid NOT NULL,company_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('resignation','company','exceptional')),notice_on date NOT NULL,last_on date NOT NULL,state text NOT NULL DEFAULT 'Requested'CHECK(state IN('Requested','Approved','Rejected','Settled')),suspended_at timestamptz,payload_cipher text NOT NULL,approved_by uuid,voucher_id uuid,UNIQUE(tenant_id,voucher_id),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,voucher_id)REFERENCES ab.finance_vouchers(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
