ALTER TABLE ab.documents ADD COLUMN employee_id uuid,ADD COLUMN personnel_library_id uuid,ADD CONSTRAINT employee_document_fk FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.hr_employees(tenant_id,id),ADD CONSTRAINT personnel_library_fk FOREIGN KEY(tenant_id,personnel_library_id)REFERENCES ab.hr_library(tenant_id,id);
ALTER TABLE ab.documents DROP CONSTRAINT documents_check;
ALTER TABLE ab.documents ADD CONSTRAINT documents_check CHECK(num_nonnulls(company_id,bank_account_id,user_id,employee_id,personnel_library_id)=1);
CREATE FUNCTION ab.hr_actor_allowed()RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,ab AS $$SELECT nullif(current_setting('ab.actor',true),'')::uuid='00000000-0000-4000-8000-000000000001'::uuid OR EXISTS(SELECT 1 FROM ab.users u WHERE u.id=nullif(current_setting('ab.actor',true),'')::uuid AND u.tenant_id=ab.tenant()AND u.status='Active'AND NOT EXISTS(SELECT 1 FROM ab.hr_employees e JOIN ab.hr_leaves l ON l.employee_id=e.id WHERE e.user_id=u.id AND l.state='Approved'AND l.suspend_account AND l.starts_on<=(timezone('Asia/Dubai',now()))::date AND l.suspended_at IS NULL)AND NOT EXISTS(SELECT 1 FROM ab.hr_employees e JOIN ab.hr_terminations t ON t.employee_id=e.id WHERE e.user_id=u.id AND t.state IN('Approved','Settled')AND t.last_on<(timezone('Asia/Dubai',now()))::date))$$;
REVOKE ALL ON FUNCTION ab.hr_actor_allowed()FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ab.hr_actor_allowed()TO ab_runtime;
