CREATE TABLE ab.hr_audit_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,employee_id uuid,actor_id uuid NOT NULL,kind text NOT NULL,payload_cipher text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,actor_id)REFERENCES ab.users(tenant_id,id));
ALTER TABLE ab.hr_audit_events ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_scope ON ab.hr_audit_events USING(tenant_id=ab.tenant())WITH CHECK(tenant_id=ab.tenant());GRANT SELECT,INSERT ON ab.hr_audit_events TO ab_runtime;
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON ab.hr_audit_events FOR EACH ROW EXECUTE FUNCTION ab.vehicle_immutable();

-- Restrict suspended accounts at the database too, while preserving active users and service jobs.
DO $$DECLARE tab text;BEGIN FOR tab IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ab'AND c.relkind='r'AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname='tenant_id'AND NOT a.attisdropped)LOOP EXECUTE format('CREATE POLICY personnel_active_actor ON ab.%I AS RESTRICTIVE TO ab_runtime USING(ab.hr_actor_allowed())WITH CHECK(ab.hr_actor_allowed())',tab);END LOOP;END $$;
CREATE FUNCTION ab.hr_terminal_history()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.state IN('Approved','Settled')THEN RAISE EXCEPTION 'approved personnel document immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER payroll_immutable BEFORE UPDATE OR DELETE ON ab.hr_payroll FOR EACH ROW EXECUTE FUNCTION ab.hr_terminal_history();
CREATE TRIGGER entitlement_immutable BEFORE UPDATE OR DELETE ON ab.hr_decisions FOR EACH ROW EXECUTE FUNCTION ab.hr_terminal_history();
CREATE INDEX personnel_search ON ab.hr_employees USING gin(search_tokens);
CREATE INDEX task_scope_due ON ab.tasks(tenant_id,company_id,employee_id,state,due_on);
REVOKE ALL ON FUNCTION ab.hr_terminal_history()FROM PUBLIC;

-- No permission grants are changed or revoked when access is held.
CREATE FUNCTION ab.hr_enforce_auth(identity uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$
DECLARE u ab.users; e ab.hr_employees; l record; source text;
BEGIN
 SELECT * INTO u FROM ab.users WHERE auth_id=identity FOR UPDATE;
 IF u.id IS NULL OR u.role_id='owner'THEN RETURN;END IF;
 SELECT * INTO e FROM ab.hr_employees WHERE user_id=u.id AND tenant_id=u.tenant_id;
 IF e.id IS NULL THEN RETURN;END IF;
 FOR l IN SELECT id,approved_by,'leave'kind FROM ab.hr_leaves WHERE employee_id=e.id AND state='Approved'AND suspend_account AND suspended_at IS NULL AND starts_on<=timezone('Asia/Dubai',now())::date
 UNION ALL SELECT id,approved_by,'termination'kind FROM ab.hr_terminations WHERE employee_id=e.id AND state IN('Approved','Settled')AND suspended_at IS NULL AND last_on<timezone('Asia/Dubai',now())::date
 LOOP
 source:=l.kind||':'||l.id;
 IF u.status='Active'THEN UPDATE ab.users SET status='Pending',revision=revision+1,updated_at=now()WHERE id=u.id;END IF;
 UPDATE ab.sessions SET expires_at=least(expires_at,now())WHERE user_id=u.id;
 INSERT INTO ab.hr_account_holds(id,tenant_id,employee_id,user_id,source_key,reason,created_by)VALUES(gen_random_uuid(),u.tenant_id,e.id,u.id,source,l.kind,l.approved_by)ON CONFLICT(tenant_id,source_key)DO NOTHING;
 IF l.kind='leave'THEN UPDATE ab.hr_leaves SET suspended_at=now()WHERE id=l.id;ELSE UPDATE ab.hr_terminations SET suspended_at=now()WHERE id=l.id;END IF;
 INSERT INTO ab.audit_events(id,tenant_id,actor_id,actor_type,action,entity_type,entity_id,fields,request_id)VALUES(gen_random_uuid(),u.tenant_id,'00000000-0000-4000-8000-000000000001','service','account_held','personnel',e.id,ARRAY['status',l.kind],gen_random_uuid());
 END LOOP;
END $$;
CREATE FUNCTION ab.hr_enforce_session(digest text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$DECLARE identity uuid;BEGIN SELECT u.auth_id INTO identity FROM ab.sessions s JOIN ab.users u ON u.id=s.user_id WHERE s.id_hash=digest;IF identity IS NOT NULL THEN PERFORM ab.hr_enforce_auth(identity);END IF;END $$;
CREATE FUNCTION ab.hr_reactivation_guard()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$BEGIN
 IF OLD.status<>'Active'AND NEW.status='Active'THEN
 IF EXISTS(SELECT 1 FROM ab.hr_employees e JOIN ab.hr_leaves l ON l.employee_id=e.id WHERE e.user_id=NEW.id AND l.state='Approved'AND l.suspend_account AND l.starts_on<=timezone('Asia/Dubai',now())::date AND l.ends_on>=timezone('Asia/Dubai',now())::date)OR EXISTS(SELECT 1 FROM ab.hr_employees e JOIN ab.hr_terminations t ON t.employee_id=e.id WHERE e.user_id=NEW.id AND t.state IN('Approved','Settled')AND t.last_on<timezone('Asia/Dubai',now())::date)THEN RAISE EXCEPTION 'active employment hold' USING ERRCODE='23514';END IF;
 UPDATE ab.hr_account_holds SET resolved_at=now()WHERE user_id=NEW.id AND resolved_at IS NULL;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER personnel_reactivation BEFORE UPDATE OF status ON ab.users FOR EACH ROW EXECUTE FUNCTION ab.hr_reactivation_guard();
REVOKE ALL ON FUNCTION ab.hr_enforce_auth(uuid),ab.hr_enforce_session(text),ab.hr_reactivation_guard()FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ab.hr_enforce_auth(uuid),ab.hr_enforce_session(text)TO ab_runtime;
-- Read-only list of explicitly enabled company jobs; no secrets or user records returned.
CREATE FUNCTION ab.hr_job_scopes()RETURNS TABLE(tenant_id uuid,company_id uuid,actor_id uuid)LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$SELECT s.tenant_id,(s.value->>'companyId')::uuid,(s.value->>'actorId')::uuid FROM ab.settings s JOIN ab.users u ON u.id=(s.value->>'actorId')::uuid AND u.tenant_id=s.tenant_id WHERE s.key LIKE 'personnel:%'AND s.value->>'personnelEnabled'='true'AND u.status='Active'$$;
REVOKE ALL ON FUNCTION ab.hr_job_scopes()FROM PUBLIC;GRANT EXECUTE ON FUNCTION ab.hr_job_scopes()TO ab_runtime;
